#!/usr/bin/env bash
# D085: full DB-backed verification against a disposable local Supabase (CI job `migrations`, or locally).
# Applies every migration from scratch, provisions throwaway QA accounts, runs E2E then the direct-REST DB tests.
set -euo pipefail
cd "$(dirname "$0")/.."
supabase=(npx --yes "supabase@${SUPABASE_CLI_VERSION:-2.122.1}")
if [ "${CI:-}" = "true" ]; then
  # Local stack keys only (generated by `supabase start`); never hosted credentials.
  eval "$("${supabase[@]}" status -o env)"
  printf 'NEXT_PUBLIC_SUPABASE_URL=%s\nNEXT_PUBLIC_SUPABASE_ANON_KEY=%s\nSUPABASE_SERVICE_ROLE_KEY=%s\nNEXT_PUBLIC_APP_URL=http://localhost:3000\nSERVICE_MODE=test_demo\nNEXT_PUBLIC_TOSS_CLIENT_KEY=test_ck_local_fixture_only\nADME_FEATURE_MAIL=on\n' \
    "$API_URL" "$ANON_KEY" "$SERVICE_ROLE_KEY" > .env.local
fi
grep -Eq '^NEXT_PUBLIC_SUPABASE_URL=http://(127\.0\.0\.1|localhost):' .env.local || { echo "refusing: local Supabase only"; exit 1; }
"${supabase[@]}" db reset --local
python3 harness/migration_check.py
node tests/support/prepare-ci-consent.mjs
node tests/provision.mjs > /dev/null
node tests/provision-admin.mjs
docker exec -i supabase_db_AD-Me psql -U postgres -v ON_ERROR_STOP=1 < tests/setup-isolated-youtube.sql
status=0
ADME_E2E_ISOLATED_YOUTUBE=1 ADME_FEATURE_INGESTION=on ADME_FEATURE_LLM=on ADME_FEATURE_TEST_BILLING=on \
  MAILPIT_URL="${MAILPIT_URL:-http://127.0.0.1:54324}" npx playwright test --reporter=line || status=1
# Some direct-REST tests reuse browser fixtures. Run the checks and recovery
# drill even when a browser assertion fails, and propagate all failures.
for t in security claims profile-fields search recruiting lists lists-public-refs proposals notifications reports privacy uploads safety retention ops analytics consent notes feedback ai-usage email-outbox selection-review ops-metrics usage-ledger promotions test-cancel; do
  echo "== $t"
  node "tests/$t.mjs" || status=1
done
node harness/restore_drill.mjs || status=1
if (( status != 0 )); then
  echo "FAIL: one or more browser, database permission or recovery checks failed"
  exit "$status"
fi
echo "PASS: migrations from scratch + E2E + DB permission tests + restore drill"
